void display_flash (Display_Type type , UInt16 flash_count, UInt16 flash_time_on, UInt16 flash_time_off)
{	
  Display_Cmd display_cmd_new ;

  timeout_stop  (display_timeout) ;	

  display_cmd_new.id = DISPLAY_FLASH ;

  display_cmd_new.arg.cmd_flash.type     = type           ;
  display_cmd_new.arg.cmd_flash.count    = flash_count    ;
  display_cmd_new.arg.cmd_flash.time_on  = flash_time_on  ;
  display_cmd_new.arg.cmd_flash.time_off = flash_time_off ;

  display_pass_cmd (& display_cmd_new) ;
}

